<template><main class="library-page"><span class="eyebrow">NOVIDADES DO SEU REPERTÓRIO</span><h1>Cantores que você segue</h1><p>Escolha seus artistas. Novas músicas publicadas depois que você começar a seguir aparecem como novidade.</p><p v-if="!user.user" class="notice">Entre para salvar seus cantores preferidos.</p><p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="library.error" class="notice">{{ library.error }}</p><div class="library-toolbar"><input v-model="search" type="search" placeholder="Encontrar cantor" aria-label="Encontrar cantor"/><button @click="load(true)">Atualizar novidades</button></div><section class="artist-picks"><article v-for="name in artists" :key="name" class="library-card"><strong>{{ name }}</strong><button :disabled="!user.user" :aria-pressed="followed(name)" @click="follow(name)">{{ followed(name)?'Seguindo · deixar de seguir':'Seguir cantor' }}</button></article></section><p v-if="!artists.length">Nenhum cantor encontrado.</p><h2>{{ news.length }} músicas novas para você</h2><div class="library-toolbar"><label class="check"><input v-model="onlyNew" type="checkbox"/> Somente novidades</label><button @click="seen" :disabled="!news.length">Marcar novidades como vistas</button></div><article v-for="track in followedTracks.slice(0,shown)" :key="trackKey(track)" class="library-card"><div class="library-row"><div class="track-info"><strong>{{ track.title }}</strong><small>{{ track.cantor }} <span v-if="isNew(track)"> · NOVA</span></small></div><div class="library-actions"><button @click="play(track)">Ouvir</button><button @click="library.openPicker([track])">Adicionar à playlist</button></div></div></article><button v-if="followedTracks.length>shown" @click="shown+=50">Mostrar mais músicas</button><p v-if="!followedTracks.length">{{ library.following.length?'Nenhuma novidade com este filtro. Desmarque “Somente novidades” para ver o repertório.':'Siga um cantor para acompanhar o repertório dele.' }}</p></main></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {getCatalog} from '@/services/catalog';import {useLibraryStore} from '@/stores/useLibraryStore';import {useUserStore} from '@/stores/userStore';import {usePlayerStore} from '@/stores/usePlayerStore';import {artistKey,isArtistNews,timeOf} from '@/utils/music-library.mjs';import {trackKey} from '@/utils/media';const library=useLibraryStore(),user=useUserStore(),player=usePlayerStore(),tracks=ref([]),search=ref(''),onlyNew=ref(true),error=ref(''),shown=ref(50);const followed=name=>library.following.some(n=>artistKey(n)===artistKey(name)),isNew=t=>isArtistNews(t,library.following,library.seen);const artists=computed(()=>[...new Set(tracks.value.map(t=>t.cantor).filter(Boolean))].filter(n=>artistKey(n).includes(artistKey(search.value))).sort((a,b)=>a.localeCompare(b,'pt-BR'))),news=computed(()=>tracks.value.filter(isNew)),followedTracks=computed(()=>tracks.value.filter(t=>followed(t.cantor)&&(!onlyNew.value||isNew(t))).sort((a,b)=>timeOf(b.createdAt)-timeOf(a.createdAt)));async function attempt(fn){try{await fn();error.value=''}catch(e){error.value=e.message}}const load=refresh=>attempt(async()=>tracks.value=await getCatalog({refresh})),follow=n=>attempt(()=>library.follow(n)),seen=()=>attempt(()=>library.markSeen());function play(t){player.addToQueue(t,{playNow:true});error.value=player.error}onMounted(()=>load(false))</script>
<style scoped>.artist-picks{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px;margin-bottom:28px}.artist-picks .library-card{display:flex;gap:12px;align-items:center;justify-content:space-between;margin:0}.artist-picks strong{min-width:0}.artist-picks button{font-size:12px}</style>